package com.nvv.mediadata.data.model.tmdbimport kotlinx.serialization.Serializable@Serializabledata class Provider (	val logoPath: String? = null,	val providerId: Int = 0,	val providerName: String = "",	val displayPriority: Int = 0)fun Provider.getLogo() : String {	return BaseURLTheMovieDatabaseImage + LogoTheMovieDatabase + (this.logoPath ?: "")}@Serializabledata class Providers (	val link: String = "",	val flatrate: List<Provider> = emptyList(),	val buy: List<Provider> = emptyList(),	val rent: List<Provider> = emptyList(),	val ads: List<Provider> = emptyList())@Serializabledata class WatchProviders(	val results: Map<String, Providers> = emptyMap())